class Solution:
    def twoOutOfThree(self, nums1: List[int], nums2: List[int], nums3: List[int]) -> List[int]:
        count = defaultdict(int)
        for arr in (nums1, nums2, nums3):
            for x in set(arr):
                count[x] += 1
        return [x for x, c in count.items() if c >= 2]

