class Solution {
public:
    vector<int> twoOutOfThree(vector<int>& nums1, vector<int>& nums2, vector<int>& nums3) {
        unordered_map<int, int> count;
        auto add = [&](vector<int>& arr) {
            unordered_set<int> seen(arr.begin(), arr.end());
            for (int x : seen) count[x]++;
        };
        add(nums1);
        add(nums2);
        add(nums3);
        vector<int> res;
        for (auto& [v, c] : count)
            if (c >= 2) res.push_back(v);
        return res;
    }
};

