class Solution:
    def twoOutOfThree(self, nums1: List[int], nums2: List[int], nums3: List[int]) -> List[int]:
        mask = [0] * 101
        for bit, arr in enumerate((nums1, nums2, nums3)):
            for x in arr:
                mask[x] |= 1 << bit
        return [v for v in range(101) if bin(mask[v]).count('1') >= 2]

