    vector<int> twoOutOfThree(vector<int>& nums1, vector<int>& nums2, vector<int>& nums3) {
        int mask[101] = {};
        vector<vector<int>*> arrays = {&nums1, &nums2, &nums3};
        for (int b = 0; b < 3; b++)
            for (int x : *arrays[b]) mask[x] |= 1 << b;
        vector<int> res;
        for (int v = 1; v <= 100; v++)
            if (__builtin_popcount(mask[v]) >= 2) res.push_back(v);
        return res;
    }
};

