var twoOutOfThree = function(nums1, nums2, nums3) {
    const mask = new Array(101).fill(0);
    [nums1, nums2, nums3].forEach((arr, b) => {
        for (const x of arr) mask[x] |= 1 << b;
    });
    const res = [];
    for (let v = 1; v <= 100; v++) {
        let m = mask[v], bits = 0;
        while (m) { bits += m & 1; m >>= 1; }
        if (bits >= 2) res.push(v);
    }
    return res;
};
